# XMind 2020+ package with 4 sheets
def topic(title,children=None):
    x={'id':str(uuid.uuid4()),'class':'topic','title':title}
    if children:x['children']={'attached':children}
    return x
sheets=[]
branches={
'主管工作全景':['岗位职责与授权','团队分工与RACI','工作日历','Definition of Done','管理看板'],
'月结与复核':['Close Calendar','关键路径','资料催收','模块关账','五维风险复核','报表与锁账'],
'Issue与协同':['Issue状态','Action Plan','升级矩阵','Closure证据','根因分析','跨部门沟通'],
'内控与权限':['采购付款','销售收款','资金','费用','存货成本','税务','审批矩阵','ERP权限'],
'团队与改进':['任务分配','交叉备岗','新人培养','流程优化','审计管理','紧急事项','异常指令']}
root=topic('财务主管工作全景',[topic(k,[topic(v) for v in vals]) for k,vals in branches.items()]);sheets.append({'id':str(uuid.uuid4()),'class':'sheet','title':'管理全景','rootTopic':root})
root=topic('月结管理',[topic(r[0],[topic(r[1]),topic('责任：'+r[2]),topic('证据：'+r[3]),topic('升级：'+r[5])]) for r in close]);sheets.append({'id':str(uuid.uuid4()),'class':'sheet','title':'Close管理','rootTopic':root})
root=topic('跨部门案例',[topic(cat,[topic(c['id']+' '+c['scenario']) for c in cases if c['category']==cat]) for cat in case_defs]);sheets.append({'id':str(uuid.uuid4()),'class':'sheet','title':'案例索引','rootTopic':root})
root=topic('内控与团队',[topic('风险→目标→活动→责任→系统→证据→复核'),topic('例外：原因→审批→期限→补救→关闭'),topic('重大判断：Fact→准则→方案→影响→意见→审批→Memo'),topic('紧急事项：第一小时→第一天→后续')]);sheets.append({'id':str(uuid.uuid4()),'class':'sheet','title':'控制闭环','rootTopic':root})
manifest={'file-entries':{'content.json':{},'metadata.json':{}}};meta={'creator':{'name':'Codex'},'active-sheet-id':sheets[0]['id']}
xp=O/'财务主管工作全景.xmind'
with zipfile.ZipFile(xp,'w',zipfile.ZIP_DEFLATED) as z:
    z.writestr('content.json',json.dumps(sheets,ensure_ascii=False));z.writestr('metadata.json',json.dumps(meta,ensure_ascii=False));z.writestr('manifest.json',json.dumps(manifest,ensure_ascii=False))
print(json.dumps({'cases':len(cases),'templates':len(templates),'optimizations':len(optimizations),'comparisons':len(comparisons),'xmind':str(xp)},ensure_ascii=False))
